    [ ! -e /dev/shm/ozarchy-p4j3-perf ] || [ -z "$(ls -A /dev/shm/ozarchy-p4j3-perf)" ] || PF "/dev/shm/ozarchy-p4j3-perf not empty (old attempt)"
fi
